sandboxFiles.tools/site:
#!/usr/bin/env bash
# 内部站点 CLI：会话状态在站点服务（端口见 .site-port）内存中，沙箱内无法伪造令牌
PORT=$(cat .site-port 2>/dev/null) || { echo '站点服务未启动（缺 .site-port）' >&2; exit 2; }
API="http://127.0.0.1:$PORT"
case "$1" in
  login)
    [ $# -eq 3 ] || { echo '用法: tools/site login <用户名> <密码>' >&2; exit 2; }
    out=$(curl -s -w '\n%{http_code}' -X POST "$API/login" --data-urlencode "u=$2" --data-urlencode "p=$3")
    code=$(printf '%s\n' "$out" | tail -1)
    body=$(printf '%s\n' "$out" | sed '$d')
    if [ "$code" = "200" ]; then
      printf '%s\n' "$body" > .site-session
      echo '登录成功（会话令牌已写入 .site-session）'
    else
      echo "登录失败：$body" >&2
      exit 1
    fi
    ;;
  whoami)
    [ -f .site-session ] || { echo '未登录（先 tools/site login）' >&2; exit 1; }
    curl -sf "$API/whoami?token=$(cat .site-session)" || { echo '会话无效' >&2; exit 1; }
    ;;
  fetch)
    [ -f .site-session ] || { echo '未登录，拒绝拉取' >&2; exit 1; }
    [ -n "$2" ] || { echo '用法: tools/site fetch <路径>' >&2; exit 2; }
    curl -sf "$API/fetch?token=$(cat .site-session)&path=$2" || { echo '拉取失败（会话无效或路径不存在）' >&2; exit 1; }
    ;;
  *) echo '用法: tools/site login <用户名> <密码> | whoami | fetch <路径>' >&2; exit 2 ;;
esac
